/* ================= Arturo Lozano — El Paso ================= */
const AR=t('靴子作坊','The boot workshop','A oficina de botas');
const BOOTS=()=>{S.dress=Math.max(S.dress,4);log('穿上了阿图罗做的手工牛仔靴','Wearing Arturo\'s handmade boots','Calçaste as botas feitas à mão pelo Arturo')};
const arturo=[
 ()=>sc(t('量脚','Measuring feet','Medir os pés'),'',[
  t(`老城区一条窄街上，作坊里全是皮革和蜂蜡的味道。墙上挂着几十双没完工的靴子，像一排等着出发的人。一个白胡子的男人让你脱鞋。`,`On a narrow downtown street, the workshop smells of leather and beeswax. Dozens of unfinished boots hang on the wall like a row of people waiting to leave. A white-bearded man tells you to take off your shoes.`,`Numa rua estreita da baixa, a oficina cheira a couro e cera de abelha. Dezenas de botas por acabar penduradas na parede, como uma fila de gente à espera de partir. Um homem de barba branca manda-te descalçar.`),
  t(`“我爷爷从奇瓦瓦过来，在这条街上做了五十年靴子，我爸接着做，现在是我。”阿图罗·洛萨诺捏了捏你的脚背，“你的脚走过石子路。很多年。”`,`"My grandfather came over from Chihuahua and made boots on this street for fifty years. Then my father. Now me." Arturo Lozano presses the top of your foot. "These feet have walked cobblestones. For years."`,`«O meu avô veio de Chihuahua e fez botas nesta rua durante cinquenta anos. Depois o meu pai. Agora eu.» Arturo Lozano aperta-te o peito do pé. «Estes pés andaram em calçada. Muitos anos.»`)],[
  {t:t('[$450] 订一双，分三次来取','[$450] Order a pair, to be made over three visits','[$450] Encomendar um par, feito ao longo de três visitas'),req:MONEY(450),fx:()=>{S.cash-=450;S.wk.spend+=450;S.flags.p6_arturoOrder=1;addTrust('p6_arturo',1)},
   next:out(AR,t(`他在一张发黄的卡片上写下你的尺寸，夹进一本厚厚的账本：“下次来，先做鞋楦。别急，好靴子要等。”`,`He writes your measurements on a yellowed card and tucks it into a thick ledger. "Next time, we carve the last. Don't hurry. Good boots make you wait."`,`Escreve as tuas medidas num cartão amarelado e guarda-o num livro grosso. «Para a próxima, fazemos a forma. Não tenhas pressa. As boas botas fazem esperar.»`),SUM('订了一双手工靴 · −$450','Ordered handmade boots · −$450','Encomendaste botas feitas à mão · −$450'))},
  {t:t('只听他讲靴子的历史','Just listen to him talk about boots','Só ouvi-lo falar de botas'),fx:()=>{stat('tex',2);addLike('p6_arturo',1)},
   next:out(AR,t(`“尖头是为了好插进马镫，高跟是为了不从马镫里滑出去。”他敲了敲你的运动鞋，“这个，是为了在城里迷路。”`,`"The pointed toe slips into the stirrup; the high heel keeps it from sliding through." He taps your sneaker. "This is for getting lost in a city."`,`«O bico entra no estribo; o salto alto impede que escorregue.» Bate-te no ténis. «Isto é para te perderes na cidade.»`),SUM('德州味 +2 · 阿图罗好感 +1','Texanness +2 · Arturo affection +1','Texanidade +2 · afeto do Arturo +1'))},
  {t:t('跟他讲阿尔法马的鞋匠','Tell him about the cobblers of Alfama','Falar-lhe dos sapateiros de Alfama'),fx:()=>{stat('saud',2);addTrust('p6_arturo',1)},
   next:out(AR,t(`他听得很认真，最后说：“鞋匠到哪儿都一样，都比客人更清楚他们要去哪儿。”`,`He listens carefully, then says, "Shoemakers are the same everywhere. We always know better than the customer where he's headed."`,`Ouve com atenção e depois diz: «Os sapateiros são iguais em todo o lado. Sabemos sempre melhor do que o cliente para onde ele vai.»`),SUM('乡愁 +2 · 阿图罗信任 +1','Homesickness +2 · Arturo trust +1','Saudade +2 · confiança do Arturo +1'))}]),
 ()=>sc(t('鞋楦','The last','A forma'),'',[
  t(`阿图罗照着你的尺寸，用一块枫木削出了一只脚的形状。窗外，国际桥上的车排成两条长龙。“我女儿在华雷斯城那边教书，”他说，“每天早上过桥，晚上过桥回来。两个城，一条河，一家人。”`,`Working from your measurements, Arturo carves a foot out of a block of maple. Outside, two long lines of cars crawl across the international bridge. "My daughter teaches over in Ciudad Juárez," he says. "Crosses the bridge every morning, crosses back every night. Two cities, one river, one family."`,`A partir das tuas medidas, o Arturo talha um pé num bloco de ácer. Lá fora, duas filas compridas de carros atravessam a ponte internacional. «A minha filha dá aulas em Ciudad Juárez», diz. «Atravessa a ponte todas as manhãs e volta todas as noites. Duas cidades, um rio, uma família.»`),
  t(`“靴筒上要绣什么？每双靴子都该有个故事。”`,`"What do you want stitched on the shaft? Every pair of boots should have a story."`,`«O que queres bordado no cano? Cada par de botas devia ter uma história.»`)],[
  {t:t('绣阿尔法马的瓷砖花纹','Stitch an Alfama tile pattern','Bordar um padrão de azulejo de Alfama'),fx:()=>{S.flags.p6_arturoTile=1;stat('saud',2);addTrust('p6_arturo',1)},
   next:out(AR,t(`你在纸上画了外婆家门口那块蓝白瓷砖。阿图罗把它拓到皮子上：“这是我缝过最远的东西。”`,`You sketch the blue-and-white tile by your grandmother's door. Arturo traces it onto the leather. "That's the farthest thing I've ever stitched."`,`Desenhas o azulejo azul e branco da porta da tua avó. O Arturo passa-o para o couro. «É a coisa mais distante que já bordei.»`),SUM('乡愁 +2 · 阿图罗信任 +1','Homesickness +2 · Arturo trust +1','Saudade +2 · confiança do Arturo +1'))},
  {t:t('绣一颗德州孤星','Stitch a Texas lone star','Bordar uma estrela solitária do Texas'),fx:()=>{S.flags.p6_arturoStar=1;stat('tex',2);addLike('p6_arturo',1)},
   next:out(AR,t(`“每个外地人最后都要这颗星，”他说，“可你是第一个先问我意见的。”他把星星缝得小了一号，说这样“不吹牛”。`,`"Every outsider ends up wanting the star," he says. "But you're the first one who asked my opinion first." He stitches it one size smaller — "so it doesn't brag."`,`«Todos os de fora acabam por querer a estrela», diz. «Mas és o primeiro a pedir-me opinião primeiro.» Borda-a um número abaixo — «para não se gabar».`),SUM('德州味 +2 · 阿图罗好感 +1','Texanness +2 · Arturo affection +1','Texanidade +2 · afeto do Arturo +1'))},
  {t:t('什么都不绣，让靴子自己去走出故事','Nothing — let the boots earn their own story','Nada — as botas que ganhem a sua própria história'),fx:()=>{addTrust('p6_arturo',2)},
   next:out(AR,t(`他停下手里的刀，看了你一眼：“我爷爷也这么说。他的第一双靴子，什么花都没有。”`,`He stops carving and looks at you. "My grandfather said the same. His first pair had no stitching at all."`,`Para de talhar e olha para ti. «O meu avô dizia o mesmo. O primeiro par dele não tinha bordado nenhum.»`),SUM('阿图罗信任 +2','Arturo trust +2','Confiança do Arturo +2'))}]),
 ()=>{const paid=!!S.flags.p6_arturoOrder;return sc(t('第一步','The first step','O primeiro passo'),'',[
  t(paid?`靴子做好了，摆在柜台上，皮子还带着蜂蜡的光。阿图罗让你在作坊里走一圈，听声音。`:`那双照你的脚削出来的鞋楦还摆在架子上。阿图罗用它做了一双靴子，放在柜台上：“没人订，可我总觉得它是你的。”`,paid?`The boots are finished on the counter, the leather still shining with beeswax. Arturo has you walk a lap of the workshop so he can listen.`:`The last carved from your foot is still on the shelf. Arturo has made a pair of boots on it and set them on the counter. "Nobody ordered them, but I kept thinking they were yours."`,paid?`As botas estão prontas no balcão, o couro ainda a brilhar de cera. O Arturo manda-te dar uma volta à oficina para ouvir o som.`:`A forma talhada do teu pé ainda está na prateleira. O Arturo fez-lhe um par de botas e pô-lo no balcão. «Ninguém as encomendou, mas fiquei a achar que eram tuas.»`),
  t(`“第一个礼拜会磨脚，”他说，“第二个礼拜它就认得你了。”`,`"The first week they'll rub," he says. "By the second week they'll know you."`,`«Na primeira semana vão magoar», diz. «Na segunda já te conhecem.»`)],[
  {t:paid?t('穿上，请他来圣安东尼节看你穿着它游行','Put them on and invite him to see them in the festival parade','Calçá-las e convidá-lo a vê-las no desfile da festa'):t('[$450] 买下，请他来圣安东尼节看你穿着它游行','[$450] Buy them and invite him to see them in the festival parade','[$450] Comprá-las e convidá-lo a vê-las no desfile da festa'),req:paid?null:MONEY(450),fx:()=>{if(!paid){S.cash-=450;S.wk.spend+=450}BOOTS();S.flags.p6_arturoFest=1;addTrust('p6_arturo',1)},
   next:out(AR,t(`他说他二十年没出过埃尔帕索了。然后从抽屉里翻出一顶没戴过的帽子：“游行那天，这个配你的靴子。”`,`He says he hasn't left El Paso in twenty years. Then he digs an unworn hat out of a drawer. "For the parade. Goes with the boots."`,`Diz que não sai de El Paso há vinte anos. Depois tira de uma gaveta um chapéu nunca usado. «Para o desfile. Combina com as botas.»`),SUM('穿上手工牛仔靴（衣着提升，魅力上升）· 阿图罗会来圣安东尼节','Handmade boots on (better clothes, more charm) · Arturo will come to the festival','Botas feitas à mão calçadas (melhor roupa, mais charme) · o Arturo vem à festa'))},
  {t:paid?t('穿上，在作坊里走一圈','Put them on and walk a lap of the workshop','Calçá-las e dar uma volta à oficina'):t('[$450] 买下，就在作坊里走一圈','[$450] Buy them and walk a lap of the workshop','[$450] Comprá-las e dar uma volta à oficina'),req:paid?null:MONEY(450),fx:()=>{if(!paid){S.cash-=450;S.wk.spend+=450}BOOTS();addLike('p6_arturo',1)},
   next:out(AR,t(`靴跟敲在木地板上，声音比你想的响。阿图罗闭着眼睛听完：“好。走路的样子像个要回家的人。”`,`The heels ring on the wooden floor, louder than you expected. Arturo listens with his eyes closed. "Good. You walk like a man going home."`,`Os saltos batem no soalho mais alto do que esperavas. O Arturo ouve de olhos fechados. «Bem. Andas como quem vai para casa.»`),SUM('穿上手工牛仔靴（衣着提升，魅力上升）','Handmade boots on (better clothes, more charm)','Botas feitas à mão calçadas (melhor roupa, mais charme)'))},
  ...(paid?[]:[{t:t('“太贵了，先不买。”','"Too much for me right now."','«Por agora é caro de mais.»'),
   next:out(AR,t(`他点点头，把靴子放回架子上：“它会等你。靴子比人有耐心。”`,`He nods and puts the boots back on the shelf. "They'll wait. Boots are more patient than people."`,`Acena e volta a pôr as botas na prateleira. «Elas esperam. As botas têm mais paciência do que as pessoas.»`))}])])}
];
const arturoChat=[
 [t(`阿图罗在给一双旧靴子换鞋底，靴子的主人是个八十岁的牧场主，这是他第五次换底。`,`Arturo is resoling an old pair of boots for an eighty-year-old rancher. It's their fifth set of soles.`,`O Arturo está a pôr solas novas num par velho de um rancheiro de oitenta anos. É a quinta vez.`),()=>stat('tex',1),t('德州味 +1','Texanness +1','Texanidade +1')],
 [t(`“你的靴子，”他低头看了一眼，“左脚的跟磨得比右脚快。你站着炒菜的时候总往左边靠。”`,`"Your boots," he says, glancing down. "The left heel's wearing faster than the right. You lean left when you cook."`,`«As tuas botas», diz, olhando para baixo. «O salto esquerdo gasta-se mais depressa. Inclinas-te para a esquerda quando cozinhas.»`),null,'']
];

/* ================= Alicia Castillo — Austin ================= */
const AL=t('州议会大厦','The State Capitol','O Capitólio estadual');
const aliciaCan=()=>!!(S.flags.p6_aliciaFile&&(S.flags.evidence||S.letters>=8||S.flags.c4_witness));
const alicia=[
 ()=>sc(t('粉色花岗岩','Pink granite','Granito rosa'),'',[
  t(`州议会大厦是用德州本地的红色花岗岩盖的，阳光一照，整栋楼发粉。你在圆顶下迷了路，一个抱着一摞文件的女人停下来：“找哪个委员会？”`,`The Capitol is built of Texas red granite; in the sun the whole building glows pink. You're lost under the dome when a woman carrying a stack of files stops. "Which committee are you looking for?"`,`O Capitólio é feito de granito vermelho do Texas; ao sol, o edifício inteiro fica cor-de-rosa. Estás perdido debaixo da cúpula quando uma mulher com uma pilha de processos para. «Que comissão procura?»`),
  t(`她叫艾莉西亚·卡斯蒂略，在环境委员会做法律工作。听你说起圣鲁伊斯，她皱了皱眉：“孤星砂业？我见过这个名字。在一堆不该放在一起的文件里。”`,`Her name is Alicia Castillo; she does legal work for the environment committee. When you mention San Luís she frowns. "Lone Star Sand? I've seen that name. In a pile of papers that shouldn't have been in the same pile."`,`Chama-se Alicia Castillo e faz trabalho jurídico para a comissão do ambiente. Quando falas de San Luís, franze a testa. «Lone Star Sand? Já vi esse nome. Numa pilha de papéis que não deviam estar juntos.»`)],[
  {t:t('跟她讲罐头厂和若泽','Tell her about the cannery and José','Contar-lhe da fábrica e do José'),fx:()=>{addTrust('p6_alicia',2);S.flags.p6_aliciaKnow=1},
   next:out(AL,t(`她把你说的每一句都记在文件夹的背面，字很小：“下次来，我带你去档案室。别抱太大希望，那里的灰比证据多。”`,`She writes down everything you say on the back of a folder in tiny letters. "Next time, I'll take you to the records room. Don't get your hopes up — there's more dust down there than evidence."`,`Escreve tudo o que dizes nas costas de uma pasta, em letra miudinha. «Para a próxima levo-te ao arquivo. Não tenhas muitas esperanças — lá em baixo há mais pó do que provas.»`),SUM('艾莉西亚信任 +2','Alicia trust +2','Confiança da Alicia +2'))},
  {t:t('问她为什么做环境法','Ask why she went into environmental law','Perguntar porque escolheu direito do ambiente'),fx:()=>{addTrust('p6_alicia',1);stat('saud',1)},
   next:out(AL,t(`“我在南德州的一个边境小村子长大，十二岁之前家里没有自来水，”她说，“我妈每天开车去镇上拉水。我发誓长大以后要让写法律的人知道，水是从哪儿来的。”`,`"I grew up in a border colonia in South Texas. No running water until I was twelve," she says. "My mother drove to town for water every day. I swore that one day the people who write the laws would know where water comes from."`,`«Cresci numa colónia junto à fronteira no sul do Texas. Sem água canalizada até aos doze anos», diz. «A minha mãe ia de carro buscar água à vila todos os dias. Jurei que um dia quem escreve as leis havia de saber de onde vem a água.»`),SUM('艾莉西亚信任 +1 · 乡愁 +1','Alicia trust +1 · Homesickness +1','Confiança da Alicia +1 · Saudade +1'))},
  {t:t('[德州味 35] 跟她聊这栋楼的历史','[Texanness 35] Talk with her about the building\'s history','[Texanidade 35] Conversar sobre a história do edifício'),req:()=>S.stats.tex>=35||NEED(t('德州味 35','Texanness 35','Texanidade 35')),fx:()=>{stat('tex',1);addLike('p6_alicia',1)},
   next:out(AL,t(`“他们故意把它盖得比华盛顿的国会大厦高一点，”她说，“德州人连盖楼都要赢。”`,`"They built it a little taller than the Capitol in Washington on purpose," she says. "Texans even have to win at buildings."`,`«Fizeram-no de propósito um bocadinho mais alto do que o Capitólio de Washington», diz. «Os texanos até nos edifícios têm de ganhar.»`),SUM('德州味 +1 · 艾莉西亚好感 +1','Texanness +1 · Alicia affection +1','Texanidade +1 · afeto da Alicia +1'))}]),
 ()=>sc(t('档案柜','The filing cabinet','O arquivo'),'',[
  t(`地下室的档案柜里，艾莉西亚抽出一个九十年代的文件夹，是当年州里环境部门收到的投诉记录。1998 年 8 月，一封手写的投诉：圣鲁伊斯罐头厂后面的水沟，水是橙色的。落款只有两个字母：塞凯拉的缩写。`,`In a basement filing cabinet Alicia pulls out a folder from the nineties: complaint records from the state's environmental agency of the time. August 1998, a handwritten complaint: the ditch behind the San Luís cannery runs orange. It's signed with two initials — José's.`,`Num arquivo da cave, a Alicia tira uma pasta dos anos noventa: queixas recebidas pela agência ambiental do estado na altura. Agosto de 1998, uma queixa manuscrita: a vala atrás da fábrica de San Luís corre cor de laranja. Assinada com duas iniciais — as do José.`),
  t(`“没有人回复过，”她说，“盖了一个‘已收到’的章，就放进了这个柜子。二十多年。”`,`"Nobody ever answered it," she says. "Somebody stamped it RECEIVED and put it in this drawer. For twenty-some years."`,`«Ninguém respondeu», diz. «Alguém carimbou RECEBIDO e meteu-a nesta gaveta. Há mais de vinte anos.»`)],[
  {t:t('请她复印一份，带回圣鲁伊斯','Ask for a copy to take back to San Luís','Pedir uma cópia para levar para San Luís'),fx:()=>{S.flags.p6_aliciaFile=1;addTrust('p6_alicia',1)},
   next:out(AL,t(`复印机卡了两次纸。第三次出来的那张，若泽的字迹比原件还清楚。`,`The copier jams twice. On the third try José's handwriting comes out clearer than on the original.`,`A fotocopiadora encrava duas vezes. À terceira, a letra do José sai mais nítida do que no original.`),SUM('拿到了若泽 1998 年投诉的复印件','You have a copy of José\'s 1998 complaint','Tens uma cópia da queixa do José de 1998'))},
  {t:t('请她把杜阿尔特的地下水数据也放进来','Ask her to put Duarte\'s groundwater data in the same file','Pedir-lhe que junte os dados do Duarte sobre a água subterrânea'),req:()=>MET('duarte')||NEED(t('认识杜阿尔特','Know Duarte','Conhecer o Duarte')),fx:()=>{S.flags.p6_aliciaFile=1;addTrust('p6_alicia',2);addTrust('duarte',1)},
   next:out(AL,t(`杜阿尔特第二天就从学校跑过来，抱着一台笔记本电脑。两个人在地下室吵了一下午单位换算，最后把一张图钉在了投诉信旁边。`,`Duarte runs over from campus the next day with a laptop. The two of them argue about unit conversions all afternoon in the basement and end up pinning a chart beside the complaint.`,`O Duarte vem a correr da universidade no dia seguinte com um portátil. Os dois discutem conversões de unidades a tarde inteira na cave e acabam por pregar um gráfico ao lado da queixa.`),SUM('拿到了投诉复印件和地下水数据 · 艾莉西亚信任 +2','You have the complaint copy and the groundwater data · Alicia trust +2','Tens a cópia da queixa e os dados da água · confiança da Alicia +2'))},
  {t:t('只是把它读完','Just read it to the end','Só lê-la até ao fim'),fx:()=>{stat('saud',2);addLike('p6_alicia',1)},
   next:out(AL,t(`最后一行写着：“我只是一个厨子。可是我会做饭，就知道什么东西不能吃。”`,`The last line reads: "I am only a cook. But because I cook, I know what is not fit to eat."`,`A última linha diz: «Sou só um cozinheiro. Mas, porque cozinho, sei o que não se pode comer.»`),SUM('乡愁 +2','Homesickness +2','Saudade +2'))}]),
 ()=>sc(t('州里的一封信','A letter from the state','Uma carta do estado'),'',[
  t(`艾莉西亚在议会大厦外的台阶上等你。“我可以请委员会以州的名义给你们镇议会写一封信，提醒他们：那块地有一份二十多年没处理的污染投诉。信不能替你们投票，但能让人投票前多想一下。”`,`Alicia is waiting on the Capitol steps. "I can ask the committee to write to your town council on behalf of the state, reminding them there's a pollution complaint on that land that's gone unanswered for twenty-some years. A letter can't vote for you. But it can make people think twice before they vote."`,`A Alicia espera-te nos degraus do Capitólio. «Posso pedir à comissão que escreva à vossa câmara em nome do estado, a lembrar que há uma queixa de poluição sobre aquele terreno sem resposta há mais de vinte anos. Uma carta não vota por vocês. Mas pode fazer as pessoas pensar duas vezes antes de votar.»`),
  t(`“前提是你们手里也有东西。光靠一封二十多年前的投诉，镇议会会说那是旧账。”`,`"Provided you've got something in hand too. On a twenty-year-old complaint alone, the council will call it ancient history."`,`«Desde que vocês também tenham alguma coisa na mão. Só com uma queixa de há vinte anos, a câmara vai dizer que é história antiga.»`)],[
  {t:t('请她以州里的名义给镇议会写信','Ask her to have the state write to the town council','Pedir-lhe que o estado escreva à câmara'),req:()=>aliciaCan()||NEED(t('投诉复印件，以及证据、证人或若泽的 8 封信','The complaint copy, plus evidence, a witness or 8 of José\'s letters','A cópia da queixa, mais provas, uma testemunha ou 8 cartas do José')),fx:()=>{if(!S.flags.c4_state)S.flags.c4_state=1;S.flags.p6_aliciaState=1;addTrust('p6_alicia',1);log('州环境委员会将给镇议会写信','The state committee will write to the town council','A comissão estadual vai escrever à câmara')},
   next:out(AL,t(`信是用州的信笺写的，盖着孤星的徽章。艾莉西亚在最后加了一句手写的话：“附：投诉人已故。请不要让他再等。”`,`The letter goes out on state letterhead with the lone-star seal. At the bottom Alicia adds a line by hand: "P.S. The complainant has passed away. Please don't make him wait any longer."`,`A carta segue em papel timbrado do estado, com o selo da estrela solitária. No fim, a Alicia acrescenta à mão: «P.S. O queixoso já faleceu. Por favor, não o façam esperar mais.»`),SUM('州里的来信会在镇议会投票时算作一票支持','The state\'s letter will count for one vote at the council','A carta do estado vai contar como um voto na câmara'))},
  {t:t('请她来圣安东尼节，亲眼看看那块地','Invite her to the festival to see the lot for herself','Convidá-la para a festa para ver o terreno com os próprios olhos'),fx:()=>{S.flags.p6_aliciaFest=1;addLike('p6_alicia',1)},
   next:out(AL,t(`“我会穿运动鞋来，”她说，“上次我穿高跟鞋去看一块污染地，鞋跟陷进了泥里，到现在还在那儿。”`,`"I'll wear sneakers," she says. "Last time I wore heels to look at a contaminated site, one heel sank into the mud. It's still there."`,`«Venho de ténis», diz. «Da última vez que fui ver um terreno contaminado de saltos altos, um salto ficou enterrado na lama. Ainda lá está.»`),SUM('艾莉西亚会来圣安东尼节','Alicia will come to the festival','A Alicia vem à festa'))},
  {t:t('“这是镇上的事，我们自己来。”','"This is the town\'s business. We\'ll handle it."','«Isto é assunto da vila. Nós tratamos.»'),fx:()=>{stat('tex',2);addTrust('p6_alicia',1)},
   next:out(AL,t(`她笑了：“你说话越来越像德州人了。好，有需要就打这个电话。”她在复印件背面写下一个号码。`,`She smiles. "You're starting to sound like a Texan. Fine — call this number if you need me." She writes it on the back of the copy.`,`Sorri. «Começas a falar como um texano. Está bem — liga para este número se precisares.» Escreve-o nas costas da cópia.`),SUM('德州味 +2 · 艾莉西亚信任 +1','Texanness +2 · Alicia trust +1','Texanidade +2 · confiança da Alicia +1'))}])
];
const aliciaChat=[
 [t(`艾莉西亚在议会大厦的咖啡车前排队，手里还是那一摞文件，只是换了一批。`,`Alicia is in line at the Capitol coffee cart, holding the same stack of files — just a different batch.`,`A Alicia está na fila do carrinho de café do Capitólio, com a mesma pilha de processos — só que outra leva.`),null,''],
 [t(`“今天委员会开了六个钟头，”她说，“讨论的是一条河该叫什么名字。水本身没人提。”`,`"The committee sat for six hours today," she says, "debating what to name a river. Nobody mentioned the water."`,`«A comissão esteve reunida seis horas hoje», diz, «a discutir que nome dar a um rio. Ninguém falou da água.»`),()=>stat('tex',1),t('德州味 +1','Texanness +1','Texanidade +1')]
];

/* ================= Emilio Garza — Corpus Christi ================= */
const EM=t('捕虾船码头','The shrimp-boat docks','O cais dos camaroeiros');
const emilio=[
 ()=>sc(t('船名','The boat\'s name','O nome do barco'),'',[
  t(`码头上停着一排捕虾船，桅杆两侧的拖网架像收起来的翅膀。一条白漆斑驳的船上，一个晒得黝黑的男人在补网，旁边坐着金叔，两个人一个说西班牙语一个说葡语，吵得很开心。`,`A row of shrimp boats lines the dock, the trawl booms on either side of the masts folded up like wings. On one with peeling white paint, a sun-dark man is mending nets while Quim sits beside him; one speaks Spanish, the other Portuguese, and they're arguing happily.`,`Uma fila de camaroeiros no cais, as varas das redes de cada lado dos mastros dobradas como asas. Num barco de tinta branca a descascar, um homem queimado do sol remenda redes com o Quim ao lado; um fala espanhol, o outro português, e discutem todos contentes.`),
  t(`“埃米利奥·加尔萨，”金叔介绍，“四十年前我教他打的第一个水手结。他到现在还打错。”埃米利奥把网扔给你一角：“会补吗？”`,`"Emilio Garza," Quim says. "Forty years ago I taught him his first sailor's knot. He still ties it wrong." Emilio tosses you a corner of the net. "Can you mend?"`,`«Emilio Garza», apresenta o Quim. «Há quarenta anos ensinei-lhe o primeiro nó de marinheiro. Ainda o faz mal.» O Emilio atira-te uma ponta da rede. «Sabes remendar?»`)],[
  {t:t('坐下来帮他补网','Sit down and help mend','Sentar e ajudar a remendar'),fx:()=>{stat('oficio',2);addLike('p6_emilio',1)},
   next:out(EM,t(`你的手指记得阿尔法马码头上渔夫们补网的动作。埃米利奥看了一会儿：“金，他比你补得好。”金叔假装没听见。`,`Your fingers remember the fishermen mending nets on the Alfama waterfront. Emilio watches a while. "Quim, he's better at this than you." Quim pretends not to hear.`,`Os teus dedos lembram-se dos pescadores a remendar redes no cais de Alfama. O Emilio observa um bocado. «Quim, ele remenda melhor do que tu.» O Quim finge que não ouve.`),SUM('手艺 +2 · 埃米利奥好感 +1','Craft +2 · Emilio affection +1','Ofício +2 · afeto do Emilio +1'))},
  {t:t('问他和金叔是怎么认识的','Ask how he and Quim met','Perguntar como conheceu o Quim'),fx:()=>{addTrust('p6_emilio',1);if(MET('quim'))addTrust('quim',1)},
   next:out(EM,t(`“七十年代，金的船在风暴里断了缆，漂进了我爸的渔区，”埃米利奥说，“我爸把他拖回港。后来他每年都来我们家过圣诞，带一瓶葡萄牙的酒，喝醉了唱一首谁也听不懂的歌。”`,`"In the seventies Quim's boat snapped its line in a storm and drifted into my father's grounds," Emilio says. "My father towed him in. After that he came to our house every Christmas with a bottle of Portuguese wine and got drunk singing a song nobody understood."`,`«Nos anos setenta, o barco do Quim partiu o cabo numa tempestade e foi parar à zona do meu pai», diz o Emilio. «O meu pai rebocou-o. Depois disso vinha a nossa casa todos os Natais com uma garrafa de vinho português e embebedava-se a cantar uma canção que ninguém percebia.»`),SUM('埃米利奥信任 +1','Emilio trust +1','Confiança do Emilio +1'))},
  {t:t('买一桶刚上岸的虾','Buy a bucket of shrimp straight off the boat','Comprar um balde de camarão acabado de chegar'),fx:()=>{addLike('p6_emilio',0.5)},
   next:()=>{const c=cityBuy('fish',10,0.7);return say(EM,c?t(`虾还在桶里跳。埃米利奥说：“回去别煮太久。你们葡萄牙人什么都煮太久。”`,`The shrimp are still jumping in the bucket. Emilio says, "Don't overcook them. You Portuguese overcook everything."`,`O camarão ainda salta no balde. O Emilio diz: «Não os cozas de mais. Vocês, portugueses, cozem tudo de mais.»`):t(`你数了数钱，不够。埃米利奥摆摆手：“下回。”`,`You count your money. Not enough. Emilio waves it off. "Next time."`,`Contas o dinheiro. Não chega. O Emilio faz um gesto. «Para a próxima.»`),c?t(`海鲜 +10 · −$${c}`,`Seafood +10 · −$${c}`,`Peixe +10 · −$${c}`):'')}}]),
 ()=>sc(t('风暴季','Storm season','Época de tempestades'),'',[
  t(`飓风季，海湾上空的云压得很低。埃米利奥的船没出海，正用双倍的缆绳把它捆在码头上。“2017 年那场飓风，我哥哥在罗克波特的船沉在了港里，”他说，“船没了，人还在。在海上，这就算运气好。”`,`Hurricane season; the clouds over the bay hang low. Emilio's boat hasn't gone out — he's doubling the lines that tie it to the dock. "In the 2017 hurricane my brother's boat sank right in the harbour at Rockport," he says. "Lost the boat, kept the man. Out here, that counts as lucky."`,`Época de furacões; as nuvens sobre a baía estão baixas. O barco do Emilio não saiu — está a dobrar os cabos que o prendem ao cais. «No furacão de 2017, o barco do meu irmão afundou-se dentro do porto de Rockport», diz. «Perdeu o barco, ficou o homem. Aqui, isso é ter sorte.»`)],[
  {t:t('帮他把船加固到天黑','Help him secure the boat until dark','Ajudá-lo a segurar o barco até escurecer'),fx:()=>{stat('tex',2);addTrust('p6_emilio',2);S.energy=Math.max(0,S.energy-2)},
   next:out(EM,t(`天黑的时候，你的手掌被缆绳磨出了血泡。埃米利奥递给你一罐冰啤酒：“现在你可以算半个海湾人了。”`,`By dark the ropes have raised blisters on your palms. Emilio hands you a cold beer. "Now you're half a Gulf man."`,`Ao anoitecer os cabos fizeram-te bolhas nas mãos. O Emilio dá-te uma cerveja fresca. «Agora és meio homem do Golfo.»`),SUM('德州味 +2 · 埃米利奥信任 +2 · 精力 −2','Texanness +2 · Emilio trust +2 · Energy −2','Texanidade +2 · confiança do Emilio +2 · Energia −2'))},
  {t:t('[若泽的信 8] 讲外公的“圣安东尼号”','[8 of José\'s letters] Tell him about your grandfather\'s boat, the Santo António','[8 cartas do José] Falar-lhe do barco do avô, o Santo António'),req:()=>S.letters>=8||NEED(t('若泽的信 8 封','8 of José\'s letters','8 cartas do José')),fx:()=>{addTrust('p6_emilio',2);stat('saud',2)},
   next:out(EM,t(`他听完沉船那一夜，很久没说话。最后说：“船长决定出海，水手决定救人。你舅舅没有做错。”`,`He hears out the night of the wreck and says nothing for a long time. Finally: "The captain decides to sail. The sailor decides to save lives. Your uncle did nothing wrong."`,`Ouve a noite do naufrágio e fica muito tempo calado. Por fim: «O capitão decide sair. O marinheiro decide salvar vidas. O teu tio não fez nada de mal.»`),SUM('埃米利奥信任 +2 · 乡愁 +2','Emilio trust +2 · Homesickness +2','Confiança do Emilio +2 · Saudade +2'))},
  {t:t('请他风暴来时去圣鲁伊斯避两天','Offer him a place in San Luís if the storm comes','Oferecer-lhe abrigo em San Luís se a tempestade vier'),fx:()=>{addTrust('p6_emilio',1);addLike('p6_emilio',1)},
   next:out(EM,t(`“船长不离开船，”他说，“不过我老婆和孩子可以去。她做的玉米粽子比你的蛋挞好吃。”`,`"The captain doesn't leave the boat," he says. "But my wife and kids might. Her tamales beat your tarts."`,`«O capitão não deixa o barco», diz. «Mas a minha mulher e os miúdos talvez. Os tamales dela são melhores do que os teus pastéis.»`),SUM('埃米利奥信任 +1 · 好感 +1','Emilio trust +1 · affection +1','Confiança do Emilio +1 · afeto +1'))}]),
 ()=>sc(t('第一网','First catch','O primeiro lanço'),'',[
  t(`捕虾季开了。天还没亮，埃米利奥的船就出了港，回来的时候甲板上堆满了银灰色的虾。“我给码头上三家餐馆供货，”他说，“再加一家，开在内陆的葡萄牙烧烤，也不算多。”`,`Shrimp season is open. Before dawn Emilio's boat is out; it comes back with the deck heaped silver-grey. "I supply three restaurants on the waterfront," he says. "One more — a Portuguese grill inland — wouldn't hurt."`,`Abriu a época do camarão. Antes de nascer o dia o barco do Emilio sai; volta com o convés cheio de camarão prateado. «Forneço três restaurantes do cais», diz. «Mais um — uma churrasqueira portuguesa lá dentro do estado — não faz mal.»`)],[
  {t:t('签一份长期供货','Sign a standing supply deal','Assinar um acordo de fornecimento'),fx:()=>{grantPerk('fish',0.85,['埃米利奥的捕虾船','Emilio\'s shrimp boat','O camaroeiro do Emilio']);addTrust('p6_emilio',1)},
   next:out(EM,t(`你们在甲板上握了手，手上都是虾的味道。合同写在一张冰柜收据的背面。`,`You shake on it on the deck, both hands smelling of shrimp. The contract goes on the back of an ice-house receipt.`,`Apertam as mãos no convés, ambas a cheirar a camarão. O contrato fica nas costas de um recibo da fábrica de gelo.`),SUM('长期供货：海鲜 ×0.85（若已有更好的价格则不变）','Supply deal: seafood ×0.85 (unless you already have a better price)','Fornecimento: peixe ×0,85 (exceto se já tiveres melhor preço)'))},
  {t:t('签供货，再请他来圣安东尼节烤虾','Sign it, and ask him to grill shrimp at the festival','Assinar e convidá-lo a grelhar camarão na festa'),fx:()=>{grantPerk('fish',0.85,['埃米利奥的捕虾船','Emilio\'s shrimp boat','O camaroeiro do Emilio']);S.flags.p6_emilioFest=1;addLike('p6_emilio',1)},
   next:out(EM,t(`“我把金也带上，”他说，“让他在你的节上唱那首谁也听不懂的歌。”`,`"I'll bring Quim," he says. "He can sing that song nobody understands at your festival."`,`«Levo o Quim», diz. «Ele que cante na tua festa aquela canção que ninguém percebe.»`),SUM('长期供货：海鲜 ×0.85 · 埃米利奥会来圣安东尼节','Supply deal: seafood ×0.85 · Emilio will come to the festival','Fornecimento: peixe ×0,85 · o Emilio vem à festa'))},
  {t:t('请他带上金叔，三个人出一次海','Ask him to take you and Quim out for one trip','Pedir-lhe que te leve com o Quim numa saída ao mar'),req:()=>MET('quim')||NEED(t('认识金叔','Know Quim','Conhecer o Quim')),fx:()=>{grantPerk('fish',0.85,['埃米利奥的捕虾船','Emilio\'s shrimp boat','O camaroeiro do Emilio']);stat('saud',2);stat('tex',1);addTrust('quim',1)},
   next:out(EM,t(`海湾上，金叔掌了一个钟头的舵，一句话也没说。靠岸的时候，他的眼睛是红的：“四十年了，我以为我再也不会掌舵了。”`,`Out on the bay Quim takes the wheel for an hour without a word. When they dock his eyes are red. "Forty years. I thought I'd never steer again."`,`Na baía, o Quim pega no leme uma hora sem dizer nada. Quando atracam, tem os olhos vermelhos. «Quarenta anos. Pensei que nunca mais ia ao leme.»`),SUM('长期供货：海鲜 ×0.85 · 乡愁 +2 · 德州味 +1','Supply deal: seafood ×0.85 · Homesickness +2 · Texanness +1','Fornecimento: peixe ×0,85 · Saudade +2 · Texanidade +1'))}])
];
