/* ================= Carlos Méndez — Houston Ship Channel ================= */
const CA=t('航道边的焊接车间','The welding shop on the Ship Channel','A oficina de soldadura no canal');
const carlos=[
 ()=>sc(t('火花','Sparks','Faíscas'),'',[
  t(`本托杂货店隔壁的焊接车间，卷帘门半开着，里面火花四溅。一个戴焊工面罩的男人掀起面罩：“你就是本托说的那个葡萄牙厨子？他说你做的鳕鱼比他的好。我不信。”`,`Next door to Bento's grocery, a welding shop's roll-up door is half open, sparks flying inside. A man in a welding mask flips it up. "You the Portuguese cook Bento keeps talking about? He says your salt cod beats his. I don't believe it."`,`Ao lado da mercearia do Bento, a porta de enrolar de uma oficina de soldadura está meio aberta, com faíscas lá dentro. Um homem de máscara de soldador levanta-a. «És o cozinheiro português de quem o Bento fala? Diz que o teu bacalhau é melhor do que o dele. Não acredito.»`),
  t(`卡洛斯·门德斯，在帕萨迪纳长大，他爸在炼油厂干了三十年。他焊的是船上的零件，航道里的大船从世界各地来，“包括你们葡萄牙”。`,`Carlos Méndez, raised in Pasadena; his father put thirty years into a refinery. He welds ship parts — the big ships on the channel come from all over the world, "yours included."`,`Carlos Méndez, criado em Pasadena; o pai deu trinta anos a uma refinaria. Solda peças de navios — os navios grandes do canal vêm de todo o mundo, «incluindo de Portugal».`)],[
  {t:t('戴上面罩，试着焊一道','Put on the mask and try one weld','Pôr a máscara e tentar uma soldadura'),fx:()=>{stat('oficio',2);addLike('p6_carlos',1)},
   next:out(CA,t(`你的焊缝歪得像一条迷路的蛇。卡洛斯看了看：“第一道都这样。我的第一道，我爸挂在家里墙上，挂了二十年。”`,`Your weld wanders like a lost snake. Carlos looks it over. "Everyone's first one looks like that. My dad hung my first on the wall at home. Twenty years."`,`A tua soldadura serpenteia como uma cobra perdida. O Carlos observa. «A primeira de toda a gente é assim. O meu pai pendurou a minha na parede lá de casa. Vinte anos.»`),SUM('手艺 +2 · 卡洛斯好感 +1','Craft +2 · Carlos affection +1','Ofício +2 · afeto do Carlos +1'))},
  {t:t('拉上本托，一起请他吃顿饭','Grab Bento and buy him dinner','Chamar o Bento e pagar-lhe o jantar'),req:()=>MET('bento')||NEED(t('认识本托','Know Bento','Conhecer o Bento')),fx:()=>{addTrust('p6_carlos',2);addLike('bento',1)},
   next:out(CA,t(`本托做了一锅巴西黑豆炖肉，卡洛斯带了一箱啤酒，你带了一盒蛋挞。三个国家的人在杂货店后屋吃到半夜，争的是哪国的足球最好。`,`Bento makes a pot of feijoada, Carlos brings a case of beer, you bring a box of tarts. Three countries eat in the grocery's back room till midnight, arguing about whose football is best.`,`O Bento faz uma panela de feijoada, o Carlos traz uma grade de cerveja, tu trazes uma caixa de pastéis. Três países comem nos fundos da mercearia até à meia-noite, a discutir qual tem o melhor futebol.`),SUM('卡洛斯信任 +2 · 本托好感 +1','Carlos trust +2 · Bento affection +1','Confiança do Carlos +2 · afeto do Bento +1'))},
  {t:t('问他航道上的事','Ask about life on the channel','Perguntar pela vida no canal'),fx:()=>{stat('tex',1);addTrust('p6_carlos',1)},
   next:out(CA,t(`“航道五十英里长，两边全是炼油厂和码头，”他说，“晚上从桥上看，像一座烧不完的城。我爸说那是钱在烧。”`,`"The channel runs fifty miles, refineries and docks on both sides," he says. "At night from the bridge it looks like a city that never stops burning. My dad said that's money burning."`,`«O canal tem cinquenta milhas, refinarias e cais dos dois lados», diz. «À noite, da ponte, parece uma cidade que nunca acaba de arder. O meu pai dizia que é dinheiro a arder.»`),SUM('德州味 +1 · 卡洛斯信任 +1','Texanness +1 · Carlos trust +1','Texanidade +1 · confiança do Carlos +1'))}]),
 ()=>sc(t('加班','Overtime','Horas extra'),'',[
  t(`飓风季前，船厂要赶工，车间里每个人一天干十六个钟头。上礼拜，一个年轻焊工从脚手架上摔下来。卡洛斯在车间门口抽烟，手在抖：“老板说那是他自己不小心。”`,`Before hurricane season the yard is racing a deadline, and everyone in the shop is working sixteen-hour days. Last week a young welder fell from a scaffold. Carlos is smoking by the shop door, his hands shaking. "The boss says it was his own carelessness."`,`Antes da época dos furacões, o estaleiro corre contra o prazo e toda a gente na oficina trabalha dezasseis horas por dia. Na semana passada, um soldador novo caiu de um andaime. O Carlos fuma à porta da oficina, com as mãos a tremer. «O patrão diz que foi descuido dele.»`)],[
  {t:t('[$60] 给车间送一大锅炖菜','[$60] Bring the whole shop a big pot of stew','[$60] Levar à oficina uma panela grande de guisado'),req:MONEY(60),fx:()=>{S.cash-=60;S.wk.spend+=60;S.rep+=1;addTrust('p6_carlos',2)},
   next:out(CA,t(`十二个焊工蹲在车间门口吃你的炖菜，谁也没说话。吃完，最老的那个把锅刷干净还给你：“下回带辣椒。”`,`Twelve welders crouch by the shop door eating your stew without a word. When they're done, the oldest scrubs the pot clean and hands it back. "Bring hot sauce next time."`,`Doze soldadores comem o teu guisado de cócoras à porta da oficina, sem uma palavra. No fim, o mais velho esfrega a panela e devolve-ta. «Para a próxima traz picante.»`),SUM('口碑 +1 · 卡洛斯信任 +2 · −$60','Reputation +1 · Carlos trust +2 · −$60','Reputação +1 · confiança do Carlos +2 · −$60'))},
  {t:t('[若泽的信 6] 讲若泽当年在罐头厂组织工人','[6 of José\'s letters] Tell him how José organised the cannery workers','[6 cartas do José] Contar-lhe como o José organizou os operários da fábrica'),req:()=>S.letters>=6||NEED(t('若泽的信 6 封','6 of José\'s letters','6 cartas do José')),fx:()=>{addTrust('p6_carlos',2);stat('tex',1);S.flags.p6_carlosJose=1},
   next:out(CA,t(`卡洛斯把烟掐了：“你舅舅被开除了，然后呢？”“然后他开了一家店，一直开到死。”他想了很久：“那我也该想想以后开什么店了。”`,`Carlos stubs out his cigarette. "Your uncle got fired. Then what?" "Then he opened a shop and kept it open till he died." He thinks for a long time. "Guess I should start thinking about what shop I'd open."`,`O Carlos apaga o cigarro. «O teu tio foi despedido. E depois?» «Depois abriu um restaurante e manteve-o aberto até morrer.» Pensa muito tempo. «Se calhar devia começar a pensar no que eu abria.»`),SUM('卡洛斯信任 +2 · 德州味 +1','Carlos trust +2 · Texanness +1','Confiança do Carlos +2 · Texanidade +1'))},
  {t:t('“先照顾好自己，别硬撑。”','"Look after yourself first. Don\'t tough it out."','«Primeiro trata de ti. Não aguentes à força.»'),fx:()=>{addLike('p6_carlos',1)},
   next:out(CA,t(`“我有三个孩子，”他说，“硬撑就是照顾自己。”不过那天晚上，他第一次准时下了班。`,`"I've got three kids," he says. "Toughing it out is looking after myself." But that night he clocks out on time for the first time.`,`«Tenho três filhos», diz. «Aguentar é tratar de mim.» Mas nessa noite sai a horas pela primeira vez.`),SUM('卡洛斯好感 +1','Carlos affection +1','Afeto do Carlos +1'))}]),
 ()=>sc(t('游行花车','The parade float','O carro alegórico'),'',[
  t(`你跟卡洛斯说起圣安东尼节的游行。他眼睛一亮：“花车需要架子。木头的会散，钢的不会。我给你焊一个，周末开车送过去。”`,`You mention the Santo António parade to Carlos. His eyes light up. "A float needs a frame. Wood falls apart; steel doesn't. I'll weld you one and drive it up on the weekend."`,`Falas ao Carlos do desfile de Santo António. Os olhos dele acendem-se. «Um carro alegórico precisa de estrutura. A madeira desfaz-se; o aço não. Eu soldo-te uma e levo-a no fim de semana.»`)],[
  {t:t('[$150] 焊一条两米长的铁皮沙丁鱼','[$150] Weld a two-metre sheet-metal sardine','[$150] Soldar uma sardinha de chapa com dois metros'),req:MONEY(150),fx:()=>{S.cash-=150;S.wk.spend+=150;S.flags.p6_carlosFest=1;addTrust('p6_carlos',1)},
   next:out(CA,t(`他发来一张照片：一条银光闪闪的铁皮沙丁鱼，眼睛是两个汽车轮毂盖。“我女儿说它在笑。”`,`He texts a photo: a gleaming sheet-metal sardine with two hubcaps for eyes. "My daughter says it's smiling."`,`Manda uma fotografia: uma sardinha de chapa reluzente com dois tampões de roda como olhos. «A minha filha diz que está a sorrir.»`),SUM('卡洛斯会把花车送来圣安东尼节 · −$150','Carlos will bring the float to the festival · −$150','O Carlos traz o carro alegórico para a festa · −$150'))},
  {t:t('[若泽的信 8] 焊一艘“圣安东尼号”的船架','[8 of José\'s letters] Weld the frame of a boat — the Santo António','[8 cartas do José] Soldar a estrutura de um barco — o Santo António'),req:()=>S.letters>=8||NEED(t('若泽的信 8 封','8 of José\'s letters','8 cartas do José')),fx:()=>{S.flags.p6_carlosFest=1;S.flags.p6_carlosBoat=1;stat('saud',2);addTrust('p6_carlos',1)},
   next:out(CA,t(`你给他看了外公那条船的旧照片。他焊了三个周末，船头用白漆写着：圣安东尼号。“这条船，”他说，“这次不会沉了。”`,`You show him the old photo of your grandfather's boat. He welds for three weekends; on the bow, in white paint: SANTO ANTÓNIO. "This one," he says, "won't sink."`,`Mostras-lhe a fotografia velha do barco do avô. Solda durante três fins de semana; na proa, a branco: SANTO ANTÓNIO. «Este», diz, «não se afunda.»`),SUM('卡洛斯会把“圣安东尼号”花车送来 · 乡愁 +2','Carlos will bring the Santo António float · Homesickness +2','O Carlos traz o carro Santo António · Saudade +2'))},
  {t:t('“不用麻烦了，路太远。”','"Don\'t trouble yourself. It\'s too far."','«Não te incomodes. É longe de mais.»'),
   next:out(CA,t(`“两百多英里，”他耸耸肩，“我们焊工一天开车比你们厨子一礼拜还多。不过好吧。”`,`"Two hundred-some miles," he shrugs. "We welders drive more in a day than you cooks do in a week. But all right."`,`«Duzentas e tal milhas», encolhe os ombros. «Nós, soldadores, conduzimos mais num dia do que vocês, cozinheiros, numa semana. Mas está bem.»`))}])
];
const carlosChat=[
 [t(`卡洛斯在给他女儿的自行车焊一个车筐，焊得比船上的零件还仔细。`,`Carlos is welding a basket onto his daughter's bike, more carefully than any ship part.`,`O Carlos está a soldar um cesto na bicicleta da filha, com mais cuidado do que qualquer peça de navio.`),null,''],
 [t(`“今天进港一艘从里斯本来的船，”他说，“船员下来买烟，我跟他们说我认识一个葡萄牙厨子。他们问我你做的鳕鱼好不好吃。我说一般。”`,`"A ship from Lisbon came in today," he says. "Crew came ashore for cigarettes. I told them I know a Portuguese cook. They asked if your salt cod's any good. I said it's okay."`,`«Hoje entrou um navio de Lisboa», diz. «A tripulação veio a terra comprar tabaco. Disse-lhes que conheço um cozinheiro português. Perguntaram se o teu bacalhau é bom. Disse que é razoável.»`),()=>stat('saud',1),t('乡愁 +1','Homesickness +1','Saudade +1')]
];

