 ['corpus','p6_docks',t('捕虾船码头','The shrimp-boat docks','O cais dos camaroeiros'),arc('emilio','corpus',t('上埃米利奥的船','Go aboard Emilio\'s boat','Subir ao barco do Emilio'),t('连续情节：金叔、风暴季、海鲜供货','Storyline: Quim, storm season, a seafood deal','História: o Quim, as tempestades, o fornecimento de peixe'),emilio,emilioChat)],
 ['laredo','p6_customs',t('国际桥边的报关行','A customs office by the international bridge','Um despachante junto à ponte internacional'),arc('marta','laredo',t('找玛尔塔','See Marta','Falar com a Marta'),t('连续情节：两岸的一家人、进口货合同','Storyline: a family on both banks, an import contract','História: uma família nas duas margens, um contrato de importação'),marta,martaChat)],
 ['houston','p6_weld',t('航道边的焊接车间','The welding shop on the Ship Channel','A oficina de soldadura no canal'),arc('carlos','houston',t('找卡洛斯','See Carlos','Falar com o Carlos'),t('连续情节：加班、若泽、游行花车','Storyline: overtime, José, the parade float','História: horas extra, o José, o carro alegórico'),carlos,carlosChat)]
